'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '../context/AuthContext';
import styles from '../page.module.css';
import authStyles from '../auth.module.css';
import Link from 'next/link';

interface Account {
  id: string;
  accountNumber: string;
  balance: number;
}

export default function Transfer() {
  const { token, isAuthenticated, logout } = useAuth();
  const router = useRouter();
  
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [fromAccountId, setFromAccountId] = useState('');
  const [toAccountNumber, setToAccountNumber] = useState('');
  const [amount, setAmount] = useState('');
  const [status, setStatus] = useState<{ type: 'error' | 'success', message: string } | null>(null);

  useEffect(() => {
    if (!isAuthenticated) {
      router.push('/login');
      return;
    }

    fetch('http://localhost:8080/api/accounts', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => {
        setAccounts(data);
        if (data.length > 0) {
          setFromAccountId(data[0].id);
        }
      });
  }, [isAuthenticated, router, token]);

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus(null);

    try {
      const res = await fetch('http://localhost:8080/api/transactions/transfer', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ fromAccountId, toAccountNumber, amount }),
      });

      const data = await res.json();

      if (res.ok) {
        setStatus({ type: 'success', message: 'Transfer successful!' });
        setAmount('');
        setToAccountNumber('');
      } else {
        setStatus({ type: 'error', message: data.error || 'Transfer failed' });
      }
    } catch (err) {
      setStatus({ type: 'error', message: 'An error occurred' });
    }
  };

  if (!isAuthenticated) return null;

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <div className={styles.logo}>Bank Modern</div>
        <nav className={styles.nav}>
          <Link href="/dashboard">Dashboard</Link>
          <Link href="/transfer">Transfer</Link>
          <Link href="/history">History</Link>
          <a href="#" onClick={(e) => { e.preventDefault(); logout(); }}>Logout</a>
        </nav>
      </header>

      <main className={styles.main}>
        <div className={authStyles.card} style={{ margin: '0 auto' }}>
          <h1 className={authStyles.title}>Transfer Funds</h1>
          {status && (
            <div className={status.type === 'error' ? authStyles.error : ''} style={status.type === 'success' ? { color: 'green', textAlign: 'center', marginBottom: '1rem' } : { marginBottom: '1rem' }}>
              {status.message}
            </div>
          )}
          <form className={authStyles.form} onSubmit={handleTransfer}>
            <div className={authStyles.inputGroup}>
              <label className={authStyles.label}>From Account</label>
              <select 
                className={authStyles.input}
                value={fromAccountId}
                onChange={(e) => setFromAccountId(e.target.value)}
                required
              >
                {accounts.map(acc => (
                  <option key={acc.id} value={acc.id}>
                    {acc.accountNumber} - ${acc.balance.toFixed(2)}
                  </option>
                ))}
              </select>
            </div>
            <div className={authStyles.inputGroup}>
              <label className={authStyles.label}>To Account Number</label>
              <input 
                type="text" 
                className={authStyles.input} 
                value={toAccountNumber}
                onChange={(e) => setToAccountNumber(e.target.value)}
                required 
              />
            </div>
            <div className={authStyles.inputGroup}>
              <label className={authStyles.label}>Amount ($)</label>
              <input 
                type="number" 
                step="0.01"
                min="0.01"
                className={authStyles.input}
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                required 
              />
            </div>
            <button type="submit" className={authStyles.button}>Send Money</button>
          </form>
        </div>
      </main>
    </div>
  );
}
